sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    if (event.payload.checked) {
        var index = event.payload.itemId.toString().slice(-1);
        var checkListArr = JSON.parse(api.state.actionItemsData);
        var checkedItemObj = checkListArr[index];
        checkedItemObj["checked"] = true;
        checkListArr[index] = checkedItemObj;
        api.setState('actionItemsData', JSON.stringify(checkListArr));
        api.setState('getChecked', (event.payload.itemId + "," + api.state.getChecked));
    } else {
        var index = event.payload.itemId.toString().slice(-1);
        var checkListArr = JSON.parse(api.state.actionItemsData);
        var checkedItemObj = checkListArr[index];
        checkedItemObj["checked"] = false;
        checkListArr[index] = checkedItemObj;
        api.setState('actionItemsData', JSON.stringify(checkListArr));
        api.setState('getChecked', api.state.getChecked);
    }
}
